// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    EtherCartel c;
    function setUp() public { c = new EtherCartel(); }

    function testFuzz_property(uint256 elapsed, address actor, address ref) public {
        vm.assume(actor != address(0));
        ref = address(uint160(bound(uint160(ref), 1, type(uint160).max)));
        elapsed = bound(elapsed, 288, 86400);

        c.seedMarket(1000);

        vm.startPrank(actor);
        c.getFreeKilo();
        uint256 kilosBefore = c.Kilos(actor);
        assertTrue(kilosBefore > 0, "setup: free kilos granted");

        vm.warp(block.timestamp + elapsed);
        c.collectDrugs(ref);
        vm.stopPrank();

        // General rule: after collectDrugs with positive production over elapsed time,
        // the caller's Kilos balance must strictly increase.
        assertTrue(c.Kilos(actor) > kilosBefore, "collectDrugs must credit produced kilos");
    }
}
